juce::String folded(const juce::String& value){if(value.isEmpty())return {};const std::wstring input(value.toWideCharPointer());const auto n=LCMapStringEx(LOCALE_NAME_INVARIANT,LCMAP_LOWERCASE,input.data(),static_cast<int>(input.size()),nullptr,0,nullptr,nullptr,0);if(n<=0)return value;std::wstring out(static_cast<std::size_t>(n),L'\0');LCMapStringEx(LOCALE_NAME_INVARIANT,LCMAP_LOWERCASE,input.data(),static_cast<int>(input.size()),out.data(),n,nullptr,nullptr,0);return juce::String(out.c_str());}
