    ToneModel* model(){auto it=std::find_if(library.models.begin(),library.models.end(),[&](const auto& m){return m.id==selected;});return it==library.models.end()?nullptr:&*it;}
    void remember(){auto& state=prefs.nativeEditor(str(slot.value));state.rigTab=tab;state.rigRole=role.getSelectedId();state.rigSearch=search.getText().substring(0,1024);state.rigTag=tags.getSelectedId()>1?tags.getText():juce::String{};state.rigFavorites=favorites.getToggleState();dirty=true;changedAt=juce::Time::getMillisecondCounter();}
    void flush(){if(!dirty)return;try{if(save)save();dirty=false;}catch(const std::exception& e){status.setText(str(e.what()),juce::dontSendNotification);}}
    void persist(){prefs.toneLibrary=str(serialize_tone_library(library));knownLibrary=prefs.toneLibrary;dirty=true;flush();}
    void pullLatest(){if(prefs.toneLibrary==knownLibrary)return;library=prefs.toneLibrary.isEmpty()?ToneLibrary{}:deserialize_tone_library(prefs.toneLibrary.toStdString());knownLibrary=prefs.toneLibrary;needsCheck=true;}
    void setTab(int id){tab=juce::jlimit(1,3,id);remember();rebuild();}
