ToneBrowser::ToneBrowser(mrs::desktop::Application& app,std::optional<mrs::Id> target,mrs::Id slot,ViewSettings& prefs,std::function<void()> save):impl(std::make_unique<Impl>(*this,app,target,slot,prefs,std::move(save))){setComponentID("tone-browser");}
ToneBrowser::~ToneBrowser()=default;
bool ToneBrowser::ready()const{return !impl->busy&&!impl->needsCheck;}
void ToneBrowser::compact(bool value){impl->compactMode=value;impl->rebuild();}
void ToneBrowser::rigLibrary(juce::Component* component,std::function<void(juce::String)> search){impl->rigPanel=component;impl->rigQuery=std::move(search);if(component)addChildComponent(*component);impl->rebuild();}
juce::Image ToneBrowser::artwork(const std::string& id)const{if(const auto* m=impl->capture(id))return impl->modelMedia(*m).image;return {};}
juce::String librarySearchKey(const juce::String& value){return folded(value);}
juce::Image loadToneArtwork(const mrs::audio::ToneModel& model){return thumbnail(model);}
void ToneBrowser::resized(){if(impl)impl->layout();}
void ToneBrowser::paint(juce::Graphics& g){drawCard(g,getLocalBounds().toFloat(),juce::Colour(contentSurface));}
void ToneBrowser::refresh(){impl->refresh();}
void ToneBrowser::importCatalog(const CabManifest& manifest){impl->importCatalog(manifest);}
void ToneBrowser::selectModel(const std::string& id){impl->select(id);}
void ToneBrowser::searchFor(const juce::String& query){if(impl->rigQuery)impl->rigQuery(query);impl->search.setText(query,false);impl->remember();impl->rebuild();}
int ToneBrowser::visibleModels()const{return static_cast<int>(impl->cards.size());}
const ToneLibrary& ToneBrowser::models()const{return impl->library;}
void ToneBrowser::setTab(int id){impl->setTab(id);}
void ToneBrowser::setRole(int id){impl->role.setSelectedId(id,juce::sendNotificationSync);}
void ToneBrowser::setFavorite(bool value){impl->pullLatest();if(auto* m=impl->model()){const auto key=tone_family(*m);for(auto& member:impl->library.models)if(tone_family(member)==key)member.favorite=value;impl->persist();impl->rebuild();}}
